	/** Crea token HMAC para el borrador */
    public function makeHmac(string $uuid, int $plantillaId, string $periodoAt, int $moduloId): string
    {
		$key_config = simad_util::readConfigFileApp(array('keyprivate_svc_password'));
		$payload = $uuid . '|' . $plantillaId . '|' . $periodoAt. '|' . $moduloId;
        return hash_hmac('sha256', $payload, $key_config['keyprivate_svc_password']);
    }
